static const int RSA_PSS_512_len=256;
/* generated + python self-verified */
static int one(const char*name,int pss,int alg,const unsigned char*ksig,int ksiglen){
  const unsigned char*msg=(const unsigned char*)RSA_MSG; intptr_t mlen=(intptr_t)strlen(RSA_MSG);
  unsigned char sig[512]; int fail=0;
  /* 1) interop: our verify accepts python's signature */
  int iv=rktcrypto_rsa_verify_msg(pss,alg,RSA_N,RSA_N_len,RSA_E,RSA_E_len,msg,mlen,ksig,ksiglen);
  /* 2) roundtrip: our sign -> our verify */
  intptr_t sl=rktcrypto_rsa_sign_msg(pss,alg,RSA_DER,RSA_DER_len,msg,mlen,sig);
  int rt=(sl>0)&&rktcrypto_rsa_verify_msg(pss,alg,RSA_N,RSA_N_len,RSA_E,RSA_E_len,msg,mlen,sig,(intptr_t)sl);
  /* 3a) tamper message -> reject (against python sig) */
  unsigned char bad[64]; memcpy(bad,msg,mlen); bad[0]^=0x01;
  int tm=(rktcrypto_rsa_verify_msg(pss,alg,RSA_N,RSA_N_len,RSA_E,RSA_E_len,bad,mlen,ksig,ksiglen)!=1);
  /* 3b) tamper signature -> reject */
  unsigned char bs[512]; memcpy(bs,ksig,ksiglen); bs[ksiglen/2]^=0x01;
  int ts=(rktcrypto_rsa_verify_msg(pss,alg,RSA_N,RSA_N_len,RSA_E,RSA_E_len,msg,mlen,bs,ksiglen)!=1);
  if(iv!=1){printf("  %s: interop-verify FAIL\n",name);fail=1;}
  if(!rt){printf("  %s: roundtrip FAIL\n",name);fail=1;}
  if(!tm){printf("  %s: tampered-msg ACCEPTED (!!)\n",name);fail=1;}
  if(!ts){printf("  %s: tampered-sig ACCEPTED (!!)\n",name);fail=1;}
  if(!fail)printf("  %s: interop OK  roundtrip OK  tamper-msg reject  tamper-sig reject\n",name);
  return !fail;
}
int main(void){ int ok=1;
  ok&=one("RSA-PKCS1-SHA256",0,RKTCRYPTO_SHA256,RSA_PKCS1_256,RSA_PKCS1_256_len);
  ok&=one("RSA-PKCS1-SHA384",0,RKTCRYPTO_SHA384,RSA_PKCS1_384,RSA_PKCS1_384_len);
  ok&=one("RSA-PKCS1-SHA512",0,RKTCRYPTO_SHA512,RSA_PKCS1_512,RSA_PKCS1_512_len);
  ok&=one("RSA-PSS-SHA256",  1,RKTCRYPTO_SHA256,RSA_PSS_256,RSA_PSS_256_len);
  ok&=one("RSA-PSS-SHA384",  1,RKTCRYPTO_SHA384,RSA_PSS_384,RSA_PSS_384_len);
  ok&=one("RSA-PSS-SHA512",  1,RKTCRYPTO_SHA512,RSA_PSS_512,RSA_PSS_512_len);
  printf("\n%s\n",ok?"ALL PASS":"FAILURES"); return ok?0:1; }
